#pragma once

// What OpenRocket's simulation options tab, its extension list and its aerodynamic lookup dialog
// show and do: the transcript of the probe tools/openrocket-probes/simulation-options
// (SimulationOptionsProbe, OpenRocket 5f164fd0e, SwingPreferences of a fresh store, FlatLaf Light,
// under xvfb), section by section ("== <section>" there), pinned by hand: copied from its
// expected.txt with the non-ASCII characters written as escapes (a line with a backslash as a raw
// string). Its BOX lines are pinned in SimulationOptionsPanelTests.cpp as relations of their own.
// A change of the probe's transcript is reviewed against these pins
// (tools/openrocket-probes/README.md).

#include <array>
#include <string_view>

